using System.Text;
using DG.Tweening;
using UnityEngine;
using TMPro;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckCheeseRolling {
public enum CheeseScreen {Setup,Play,Join,Pause,Help,Settings,Result,Confirm}
public sealed class CheeseMenus:SportsMenuView {
 public CheeseHudPresentation presentation;public CheeseMatch match;public TMP_InputField[] names;public TMP_Text[] sources,levels,pads;public GameObject[] rows;public TMP_Text countText,setupInfo,joinInfo,resultText,confirmText;public RectTransform[] views;public TMP_Text[] headers,footers,indicators,countdowns;public RectTransform[] startBadges;public UnityEngine.UI.Image[] startRings,startCharges;int lastBeat=-1;
 public CheeseScreen Screen{get;private set;}bool dirty=true;float nextHUD;int returnPage,helpPage;string confirm;readonly StringBuilder text=new StringBuilder(700);SportsMenuAction[] joinActions;
 public const string Help="HARDCORE TRUCK CHEESE ROLLING\nCHASE THE CHEESE\nStart together on the broad, high flat meadow, accelerate into the smooth transition, then hurtle down the enormous hillside into the muddy runout. Starting slots shuffle across the full sixteen-position grid, including the outside. Trees have breakable physical roots: trucks and exploding sheep can knock them fully down, and fallen trunks stay collidable. Rocks, cats, wolves and tall-grass patches change each round, with clear routes preserved. Only the marked, colored participants can score. Twelve background racers create chaos but never earn or consume points. First genuine truck-body contact earns one catch. First to five wins. Solo is a timed five-catch challenge. There is no finish-line score.\n\nCONTROLS\nYour assigned keyboard cluster or stick steers and accelerates. Opposite throttle brakes before reversing. Whole controller: left stick steer, RT forward, LT reverse; Y/North recovers. Esc / assigned Start pauses. Each player can RECOVER from the pause screen, including shared-stick players. Airborne input gives a small bounded correction. Momentum remains live while tumbling or damaged.\n\nWEATHER AND HAZARDS\nClear, blizzard, and hurricane conditions rotate with the round seed. Snow lowers grip; rain makes the runout slick; everyone feels the same gusts. Cheese stays indestructible. Actual sheep have explosive red collars. Truck contact triggers a powerful broad blast, temporary damage and nearby chain reactions. Steer around them or risk a spectacular launch.\n\nFAIR CATCHES\nDramatic 3 / 2 / 1 / GO: begin accelerating while 2 is displayed, then hold through GO for a jump boost. Pressing early or late does not qualify; releasing cancels it. AI obeys the same timing rule. The cheese gets a short head start during 1. Background contact never stops scoring. Contacts from different participants in the same physics step cause a neutral replay with unchanged scores. Cheese escaping or genuinely unreachable also replays neutrally. Low-speed mud chases remain live.\n\nRECOVERY\nRecovery uses a safe nearby point at or behind prior progress, at least nine metres behind the cheese, avoiding trucks and blast sites. It clears dangerous motion, has a five-second cooldown, and requires separation before scoring. Damage reduces control briefly without stopping flight or sliding.\n\nSETUP AND PAUSE\nOne to four participants, any human/AI combination, independent difficulties. Names, sources and colors persist through rematches. Whole controllers have one owner; independent left/right sticks can share one pad. Disconnect pauses the entire race without losing bodies, scores or weather. Assign replacement explicitly and release controls before resuming. The mushroom look reuses Taxi's world-wave shader and vivid grading with a sport-owned sky. Pause → MUSHROOM LOOK cycles full / low / off. It never affects physics or the HUD. No networking, collectible powerups, cancellation scoring or permanent elimination.";
 static readonly int HelpSplit=Help.IndexOf("FAIR CATCHES");static readonly string[] HelpPages={Help.Substring(0,HelpSplit),Help.Substring(HelpSplit)};
 public void NextHelp(){helpPage=1-helpPage;HelpText();}
 void HelpText(){pages[4].transform.Find("Rules").GetComponent<TMP_Text>().text=HelpPages[helpPage];pages[4].transform.Find("Title").GetComponent<TMP_Text>().text="HARDCORE TRUCK CHEESE ROLLING · HELP "+(helpPage+1)+" / 2";}
 protected override void Start(){base.Start();joinActions=pages[2].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<4;i++){int slot=i;names[i].onEndEdit.AddListener(value=>{match.setup.players[slot].name=string.IsNullOrWhiteSpace(value)?"Player "+(slot+1):value.Trim();match.Save();});}Show(Screen);}
 public void Dirty(){dirty=true;}
 void CountdownHUD(){int beat=match.Starting?match.Countdown:match.Live&&match.RaceTime<.8f?0:-1;bool changed=beat!=lastBeat;lastBeat=beat;for(int i=0;i<match.setup.count;i++){var badge=startBadges[i];badge.gameObject.SetActive(beat>=0);if(beat<0)continue;bool charged=match.BoostReady(i);countdowns[i].text=beat==0?"GO":beat.ToString();countdowns[i].color=Color.white;startRings[i].fillAmount=beat==0?1:1-Mathf.Repeat(match.StartElapsed,1);startRings[i].color=charged?new Color(.35f,1,.83f):new Color(1,.78f,.28f);startCharges[i].color=new Color(.35f,1,.83f,charged?1:0);if(changed&&!match.setup.reducedMotion){badge.DOKill();badge.localScale=Vector3.one;badge.DOPunchScale(Vector3.one*.1f,.35f,2).SetLink(badge.gameObject);}}}

 public void LayoutView(int i,Rect rect,bool enabled){views[i].anchorMin=new Vector2(rect.xMin,rect.yMin);views[i].anchorMax=new Vector2(rect.xMax,rect.yMax);views[i].offsetMin=views[i].offsetMax=Vector2.zero;views[i].gameObject.SetActive(enabled&&Screen==CheeseScreen.Play);}
 public void Show(CheeseScreen screen){Screen=screen;if(screen==CheeseScreen.Result){var title=pages[6].transform.Find("Title");title.DOKill();title.localScale=Vector3.one;title.DOPunchScale(Vector3.one*.04f,.4f,3).SetUpdate(true).SetLink(title.gameObject);}if(screen==CheeseScreen.Help){helpPage=0;HelpText();}base.Show((int)screen);for(int i=0;i<4;i++)views[i].gameObject.SetActive(screen==CheeseScreen.Play&&match.cameras[i].view.enabled);if(screen==CheeseScreen.Settings)SettingsText();dirty=true;Refresh();}
 public override void Action(string key){if(match.InMatch&&!match.Finished&&Screen!=CheeseScreen.Play&&!match.MenuConfirm())return;base.Action(key);if(key.StartsWith("recover")){int i=int.Parse(key.Substring(7));if(i<match.setup.count)match.trucks[i].Recover();return;}if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){var p=match.setup.players[int.Parse(key.Substring(5))];p.difficulty=(BowlingDifficulty)(((int)p.difficulty+1)%3);match.Save();return;}if(key.StartsWith("pad")){match.NextPad(int.Parse(key.Substring(3)));return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}
  switch(key){case "look":match.look.Cycle();break;case "helpnext":NextHelp();break;case "count":match.setup.count=match.setup.count%4+1;match.Save();break;case "allai":match.AllAI();break;case "start":case "rematch":match.StartMatch();break;case "resume":match.Resume();break;case "setup":match.ChangeSetup();break;case "help":returnPage=(int)Screen;Show(CheeseScreen.Help);break;case "settings":returnPage=(int)Screen;Show(CheeseScreen.Settings);break;case "back":Show(Screen==CheeseScreen.Join?CheeseScreen.Setup:(CheeseScreen)returnPage);break;case "restart":case "front":if(match.InMatch&&!match.Finished){confirm=key;confirmText.text=key=="restart"?"Restart Hardcore Truck Cheese Rolling?\nCatch scores reset; participants are retained.":"Return to sport selection?\nThe current race will be abandoned.";match.Gate();Show(CheeseScreen.Confirm);}else{match.Save();SportsNavigation.FrontEnd();}break;case "no":Show(CheeseScreen.Pause);break;case "yes":if(confirm=="restart")match.StartMatch();else{match.Save();SportsNavigation.FrontEnd();}break;}
  dirty=true;Refresh();
 }
 void Refresh(){if(!dirty)return;dirty=false;var s=match.setup;if(Screen==CheeseScreen.Setup){countText.text=s.count+(s.count==1?" PARTICIPANT · SOLO CHALLENGE":" PARTICIPANTS · SIMULTANEOUS");for(int i=0;i<4;i++){rows[i].SetActive(i<s.count);var p=s.players[i];names[i].SetTextWithoutNotify(p.name);names[i].textComponent.color=p.color;sources[i].text=p.source==BowlingSource.Keyboard?p.forward+"/"+p.left+"/"+p.back+"/"+p.right:p.source.ToString().ToUpper();sources[i].color=p.color;levels[i].text=p.source==BowlingSource.AI?p.difficulty.ToString().ToUpper():"HUMAN";levels[i].transform.parent.gameObject.SetActive(p.source==BowlingSource.AI);pads[i].transform.parent.gameObject.SetActive(p.Controller);pads[i].text=match.Ready(i)&&p.pad!=null?"PAD #"+p.pad.deviceId:"ASSIGN PAD";}setupInfo.text=s.Validate(out var reason)?"First to five catches · 12 additional background racers\nWhole controllers exclusive; left/right stick sources may share one pad. North / Y joins in the device screen.":reason;Focus();}
  if(Screen==CheeseScreen.Join){text.Clear().Append("North / Y / Triangle joins the next unassigned source.\nUse REASSIGN for explicit replacement. Release all controls before resuming.\n\n");for(int i=0;i<s.count;i++){var p=s.players[i];text.Append(p.name).Append(" \u00b7 ").Append(p.source).Append(" \u00b7 ").Append(match.Ready(i)?p.pad!=null?p.pad.displayName+" #"+p.pad.deviceId:"READY":"NOT CONNECTED").Append('\n');}joinInfo.text=text.ToString();if(joinActions!=null)foreach(var a in joinActions){if(a.action.StartsWith("reassign")){int i=int.Parse(a.action.Substring(8));a.gameObject.SetActive(i<s.count&&s.players[i].Controller);}if(a.action=="resume")a.button.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}}
  if(Screen==CheeseScreen.Result){text.Clear().Append("HARDCORE TRUCK CHEESE ROLLING\n").Append(match.setup.count==1?"SOLO FIVE-CATCH CHALLENGE COMPLETE":match.setup.players[match.Winner].name+" WINS").Append("\nElapsed ").Append(match.Elapsed.ToString("F1")).Append("s\n\n");for(int i=0;i<s.count;i++)text.Append(s.players[i].name).Append("   ").Append(match.totals[i]).Append(" / 5 CATCHES\n");resultText.text=text.ToString();presentation?.Results();}
 }
 protected override void Update(){base.Update();Refresh();if(Screen==CheeseScreen.Play)CountdownHUD();if(Screen!=CheeseScreen.Play||Time.unscaledTime<nextHUD)return;nextHUD=Time.unscaledTime+.1f;for(int i=0;i<match.setup.count;i++){var t=match.trucks[i];text.Clear().Append(match.setup.players[i].name).Append("  <b>").Append(match.totals[i]).Append(" / 5</b>").Append(match.setup.count==1?"  ·  "+match.Elapsed.ToString("F1")+"s":"  ·  Round "+match.Round).Append('\n');for(int j=0;j<match.setup.count;j++){if(j>0)text.Append("   ");text.Append("P").Append(j+1).Append(' ').Append(match.totals[j]);}headers[i].text=text.ToString();headers[i].color=new Color(.93f,.96f,1);
   footers[i].text=match.Phase==CheesePhase.Settling?"Getting settled on the grid…":match.Phase==CheesePhase.Result?match.Notice:t.DisabledFor>0?"Wrecked   /   "+t.DisabledFor.ToString("F1")+"s":t.RecoveryCooldown>0?"Recovering   /   "+t.RecoveryCooldown.ToString("F1")+"s":match.weather.Description+"   /   "+(t.Mud?"Mud runout":"Downhill chase");
   var p=match.cameras[i].view.WorldToViewportPoint(match.cheese.body.position);bool outside=p.z<0||p.x<.08f||p.x>.92f||p.y<.15f||p.y>.82f;var r=indicators[i].rectTransform;if(p.z<0){p.x=1-p.x;p.y=1-p.y;}r.anchorMin=r.anchorMax=new Vector2(Mathf.Clamp(p.x,.16f,.84f),Mathf.Clamp(p.y,.24f,.77f));r.anchoredPosition=Vector2.zero;indicators[i].text=(outside?(p.x<.08f?"← ":p.x>.92f?"→ ":p.y<.15f?"↓ ":"↑ "):"▼ ")+""+Mathf.RoundToInt(Vector3.Distance(t.body.position,match.cheese.body.position))+"m";indicators[i].gameObject.SetActive(match.InMatch);
  }presentation?.Refresh();}
}
}
